import ast

def to_tree(node):
    if isinstance(node, ast.Name):
        return node.id
    assert isinstance(node, ast.BinOp)
    operators = {ast.Add: '+', ast.Sub: '-', ast.Mult: '*', ast.Div: '/'}
    return (operators[type(node.op)], to_tree(node.left), to_tree(node.right))

tree = ('-', ('*', ('+', 'a', 'b'), 'c'), ('/', 'd', ('-', 'e', 'f')))
text = serialize_expression(tree)
assert text == '(a+b)*c-d/(e-f)'
assert to_tree(ast.parse(text, mode='eval').body) == tree
